# Load required packages
library(readr)
library(dplyr)

# ------------------------------------------------------------------
# Helper: convert negative missing codes to the standard codes as per the metadata
recode_missing <- function(x) {
  # Convert to numeric (NA for non‑numeric)
  x_num <- as.numeric(x)

  # Mapping of common negative codes to the standard missing codes
  mapping <- list(
    `-999` = -2, `-998` = -2, `-997` = -2, `-995` = -2,   # schedule not applicable / error
    `-1`   = -1,                                      # item not applicable
    `-8`   = -8,                                      # insufficient information
    `-92`  = -9,                                      # refused
    `-94`  = -8,                                      # insufficient information / script loss
    `-9`   = -9,                                      # refusal
    `-99`  = -3,                                      # not asked / not interviewed
    `-91`  = -1                                       # item not applicable
  )

  res <- x_num
  for (i in seq_along(x_num)) {
    val <- x_num[i]
    if (!is.na(val) && val < 0) {
      key <- as.character(val)
      if (key %in% names(mapping)) {
        res[i] <- mapping[[key]]
      } else {
        res[i] <- -3   # default to “not asked”
      }
    }
  }
  res
}

# ------------------------------------------------------------------
# Map the full NS‑SEC operational categories to the 5 major NS‑SEC categories
# (coarse mapping based on the SOC structure)
map_major_nssec <- function(vals) {
  sapply(vals, function(v) {
    if (is.na(v)) return(NA_real_)

    # Major 1: higher managerial & professional (codes 1‑6, 10)
    if (v %in% c(1,2,3,4,5,6,10)) return(1)
    # Major 2: lower managerial & supervisory (codes 5,6,10)
    if (v %in% c(5,6,10)) return(2)
    # Major 3: intermediate (codes 7‑9)
    if (v %in% c(7,8,9)) return(3)
    # Major 4: routine & semi‑routine (codes 11‑13)
    if (v %in% c(11,12,13)) return(4)
    # Major 5: non‑employed (codes 14‑16)
    if (v %in% c(14,15,16)) return(5)

    # Detailed decimal categories
    if (v %in% c(3.1,3.2,3.3,3.4,4.1,4.2,4.3,4.4)) return(1)
    if (v %in% c(5.0,6.0,10.0)) return(2)
    if (v %in% c(7.1,7.2,7.3,7.4,8.1,8.2,9.1,9.2)) return(3)
    if (v %in% c(11.1,11.2,12.1,12.2,12.3,12.4,12.5,12.6,12.7,
                 13.1,13.2,13.3,13.4,13.5)) return(4)
    if (v %in% c(14.1,14.2,14.3,15.0,16.0)) return(5)

    NA_real_
  })
}

# ------------------------------------------------------------------
# Function to read a tab‑delimited file safely
read_wave <- function(path) {
  if (!file.exists(path)) return(NULL)
  df <- tryCatch(
    read_delim(path, delim = "\t", col_types = cols(), na = c("", "NA")),
    error = function(e) NULL
  )
  if (is.null(df) || nrow(df) == 0) return(NULL)
  df
}

# ------------------------------------------------------------------
# Load all waves (files listed in the metadata)
wave4 <- read_wave("data/input/wave_four_lsype_young_person_2020.tab")   # age 17
wave5 <- read_wave("data/input/wave_five_lsype_young_person_2020.tab")   # age 18
wave6 <- read_wave("data/input/wave_six_lsype_young_person_2020.tab")    # age 19
wave7 <- read_wave("data/input/wave_seven_lsype_young_person_2020.tab")   # age 20
wave8 <- read_wave("data/input/ns8_2015_derived.tab")                    # age 25
wave9 <- read_wave("data/input/ns9_2022_main_interview.tab")              # age 32

# ------------------------------------------------------------------
# Process each wave: create raw variable, then map to major category
if (!is.null(wave4)) {
  wave4 <- wave4 %>%
    mutate(nssec17_raw  = recode_missing(W4nsseccatYP),
           nssec17      = map_major_nssec(nssec17_raw))
}
if (!is.null(wave5)) {
  wave5 <- wave5 %>%
    mutate(nssec18_raw  = recode_missing(W5nsseccatYP),
           nssec18      = map_major_nssec(nssec18_raw))
}
if (!is.null(wave6)) {
  wave6 <- wave6 %>%
    mutate(nssec19_raw  = recode_missing(w6nsseccatYP),
           nssec19      = map_major_nssec(nssec19_raw))
}
if (!is.null(wave7)) {
  wave7 <- wave7 %>%
    mutate(nssec20_raw  = recode_missing(W7NSSECCat),
           nssec20      = map_major_nssec(nssec20_raw))
}
if (!is.null(wave8)) {
  wave8 <- wave8 %>%
    mutate(nssec25_raw  = recode_missing(W8DNSSEC17),
           nssec25      = map_major_nssec(nssec25_raw))
}
if (!is.null(wave9)) {
  wave9 <- wave9 %>%
    mutate(nssec32_raw  = recode_missing(W9NSSEC),
           nssec32      = map_major_nssec(nssec32_raw))
}

# ------------------------------------------------------------------
# Helper to create an empty data frame with the required variable
make_empty <- function(var_name) {
  data.frame(NSID = character(), setNames(data.frame(x = numeric()), var_name), stringsAsFactors = FALSE)
}

# Build output frames for each wave
out4 <- if (!is.null(wave4)) wave4 %>% select(NSID, nssec17) else make_empty("nssec17")
out5 <- if (!is.null(wave5)) wave5 %>% select(NSID, nssec18) else make_empty("nssec18")
out6 <- if (!is.null(wave6)) wave6 %>% select(NSID, nssec19) else make_empty("nssec19")
out7 <- if (!is.null(wave7)) wave7 %>% select(NSID, nssec20) else make_empty("nssec20")
out8 <- if (!is.null(wave8)) wave8 %>% select(NSID, nssec25) else make_empty("nssec25")
out9 <- if (!is.null(wave9)) wave9 %>% select(NSID, nssec32) else make_empty("nssec32")

# ------------------------------------------------------------------
# Merge all waves by NSID
merged <- full_join(out4, out5, by = "NSID") %>%
  full_join(., out6, by = "NSID") %>%
  full_join(., out7, by = "NSID") %>%
  full_join(., out8, by = "NSID") %>%
  full_join(., out9, by = "NSID")

# Replace remaining NA (no data at all) with the standard “not asked” code (-3)
merged[is.na(merged)] <- -3

# ------------------------------------------------------------------
# Write the cleaned data to CSV (exactly one file)
write_csv(merged, "data/output/cleaned_data.csv")
```

