library(readr)
library(dplyr)
library(tidyr)
library(labelled)

# helper to map negative missing values based on value_labels
recode_missing <- function(x, val_labels) {
  # val_labels is named vector of labels; names are numeric as strings
  # Define mapping
  mapping <- list(
    '-999' = '-2', '-998' = '-2', '-997' = '-2', '-995' = '-2',
    '-1'   = '-1',
    '-8'   = '-8', '-92'  = '-9', '-94' = '-8',
    '-9'   = '-9', '-92'  = '-9',
    '-99'  = '-3',
    '-91'  = '-1'
  )
  # default mapping for other negatives
  res <- x
  for (i in seq_along(x)) {
    val <- as.character(x[i])
    if (!is.na(as.numeric(x[i]))) {
      if (x[i] < 0) {
        # find in mapping
        if (val %in% names(mapping)) {
          res[i] <- as.numeric(mapping[[val]])
        } else {
          res[i] <- -3
        }
      }
    }
  }
  res
}

# function to convert full operational NS-SEC to major category 1-5
map_major_nssec <- function(val) {
  # val numeric or NA
  if (is.na(val)) return(NA_real_)
  # category mapping based on standard NS-SEC major
  # 1: Higher managerial & professional (codes 1-4.x)
  # 2: Lower managerial & supervisory (codes 5-6.x,10.0)
  # 3: Intermediate (codes 7.x, 8.x, 9.x)
  # 4: Routine & semi routine (codes 11.x, 12.x, 13.x)
  # 5: Non-employed (14.x, 15.0, 16.0)
  if (val %in% c(1,2,3,4,5,6,10)) {
    return(1)
  }
  if (val %in% c(7,8,9)) {
    return(3)
  }
  if (val %in% c(11,12,13)) {
    return(4)
  }
  if (val %in% c(14,15,16)) {
    return(5)
  }
  # for subcodes with decimals
  if (val %in% c(3.1,3.2,3.3,3.4,4.1,4.2,4.3,4.4)) return(1)
  if (val %in% c(5.0,6.0,10.0)) return(2)
  if (val %in% c(7.1,7.2,7.3,7.4,8.1,8.2,9.1,9.2)) return(3)
  if (val %in% c(11.1,11.2,12.1,12.2,12.3,12.4,12.5,12.6,12.7,13.1,13.2,13.3,13.4,13.5)) return(4)
  if (val %in% c(14.1,14.2,14.3,15.0,16.0)) return(5)
  return(NA_real_)
}

# Read files
wave4 <- read_delim("data/input/wave_four_lsype_young_person_2020.tab", delim = "\t", col_types = cols(), na = c("", "NA"))
wave5 <- read_delim("data/input/wave_five_lsype_young_person_2020.tab", delim = "\t", col_types = cols(), na = c("", "NA"))
wave6 <- read_delim("data/input/wave_six_lsype_young_person_2020.tab", delim = "\t", col_types = cols(), na = c("", "NA"))
wave7 <- read_delim("data/input/wave_seven_lsype_young_person_2020.tab", delim = "\t", col_types = cols(), na = c("", "NA"))
wave8 <- read_delim("data/input/ns8_2015_derived.tab", delim = "\t", col_types = cols(), na = c("", "NA"))
wave9 <- read_delim("data/input/ns9_2022_main_interview.tab", delim = "\t", col_types = cols(), na = c("", "NA"))

# Harmonise missing values for each wave
# Wave4 (age 17)
wave4 <- wave4 %>% mutate(
  nssec17_raw = recode_missing(W4nsseccatYP, NULL),
  nssec17 = map_major_nssec(nssec17_raw)
)
# Wave5 (age 18)
wave5 <- wave5 %>% mutate(
  nssec18_raw = recode_missing(W5nsseccatYP, NULL),
  nssec18 = map_major_nssec(nssec18_raw)
)
# Wave6 (age 19)
wave6 <- wave6 %>% mutate(
  nssec19_raw = recode_missing(w6nsseccatYP, NULL),
  nssec19 = map_major_nssec(nssec19_raw)
)
# Wave7 (age 20)
wave7 <- wave7 %>% mutate(
  nssec20_raw = recode_missing(W7NSSECCat, NULL),
  nssec20 = map_major_nssec(nssec20_raw)
)
# Wave8 (age 25)
wave8 <- wave8 %>% mutate(
  nssec25_raw = recode_missing(W8DNSSEC17, NULL),
  nssec25 = map_major_nssec(nssec25_raw)
)
# Wave9 (age 32)
wave9 <- wave9 %>% mutate(
  nssec32_raw = recode_missing(W9NSSEC, NULL),
  nssec32 = map_major_nssec(nssec32_raw)
)

# Select only ID and new variables
wave4_out <- wave4 %>% select(NSID, nssec17)
wave5_out <- wave5 %>% select(NSID, nssec18)
wave6_out <- wave6 %>% select(NSID, nssec19)
wave7_out <- wave7 %>% select(NSID, nssec20)
wave8_out <- wave8 %>% select(NSID, nssec25)
wave9_out <- wave9 %>% select(NSID, nssec32)

# Merge all waves by NSID
merged <- full_join(wave4_out, wave5_out, by = "NSID") %>%
  full_join(., wave6_out, by = "NSID") %>%
  full_join(., wave7_out, by = "NSID") %>%
  full_join(., wave8_out, by = "NSID") %>%
  full_join(., wave9_out, by = "NSID")

# Convert missing codes to standard numeric sentinel where NA
for (col in c("nssec17","nssec18","nssec19","nssec20","nssec25","nssec32")) {
  merged[[col]] <- ifelse(is.na(merged[[col]]), -3, merged[[col]])
}

# Write output
write_csv(merged, "data/output/cleaned_data.csv")

