library(readr)
library(dplyr)
library(tidyr)
library(labelled)

# Helper to map negative missing values based on value_labels
recode_missing <- function(x, val_labels) {
  # Convert to numeric, keep NAs
  x_num <- as.numeric(x)
  # Define mapping for common negative codes
  mapping <- list(
    `-999` = -2,
    `-998` = -2,
    `-997` = -2,
    `-995` = -2,
    `-1`   = -1,
    `-8`   = -8,
    `-92`  = -9,
    `-94`  = -8,
    `-9`   = -9,
    `-99`  = -3,
    `-91`  = -1
  )
  res <- x_num
  for (i in seq_along(x_num)) {
    val <- x_num[i]
    if (!is.na(val) && val < 0) {
      key <- as.character(val)
      if (key %in% names(mapping)) {
        res[i] <- mapping[[key]]
      } else {
        res[i] <- -3
      }
    }
  }
  res
}

# Convert full operational NS-SEC to major category 1-5
map_major_nssec <- function(vals) {
  sapply(vals, function(val) {
    if (is.na(val)) return(NA_real_)
    # direct integer or decimal
    if (val %in% c(1,2,3,4,5,6,10)) {
      return(1)
    }
    if (val %in% c(7,8,9)) {
      return(3)
    }
    if (val %in% c(11,12,13)) {
      return(4)
    }
    if (val %in% c(14,15,16)) {
      return(5)
    }
    if (val %in% c(3.1,3.2,3.3,3.4,4.1,4.2,4.3,4.4)) return(1)
    if (val %in% c(5.0,6.0,10.0)) return(2)
    if (val %in% c(7.1,7.2,7.3,7.4,8.1,8.2,9.1,9.2)) return(3)
    if (val %in% c(11.1,11.2,12.1,12.2,12.3,12.4,12.5,12.6,12.7,13.1,13.2,13.3,13.4,13.5)) return(4)
    if (val %in% c(14.1,14.2,14.3,15.0,16.0)) return(5)
    return(NA_real_)
  })
}

