wave4 <- read_delim("data/input/wave_four_lsype_young_person_2020.tab", delim = "\t", col_types = cols(), na = c("", "NA"))
wave5 <- read_delim("data/input/wave_five_lsype_young_person_2020.tab", delim = "\t", col_types = cols(), na = c("", "NA"))
wave6 <- read_delim("data/input/wave_six_lsype_young_person_2020.tab", delim = "\t", col_types = cols(), na = c("", "NA"))
