library(readr)
library(dplyr)
library(tidyr)
library(labelled)

# Helper to map negative missing values
recode_missing <- function(x) {
  x_num <- as.numeric(x)
  mapping <- list(`-999` = -2, `-998` = -2, `-997` = -2, `-995` = -2,
                   `-1` = -1, `-8` = -8, `-92` = -9, `-94` = -8,
                   `-9` = -9, `-99` = -3, `-91` = -1, `-92` = -9)
  res <- x_num
  for (i in seq_along(x_num)) {
    val <- x_num[i]
    if (!is.na(val) && val < 0) {
      key <- as.character(val)
      if (key %in% names(mapping)) {
        res[i] <- mapping[[key]]
      } else {
        res[i] <- -3
      }
    }
  }
  res
}

# Map to major NS-SEC 1-5
map_major_nssec <- function(vals) {
  sapply(vals, function(v) {
    if (is.na(v)) return(NA_real_)
    if (v %in% c(1,2,3,4,5,6,10)) return(1)
    if (v %in% c(7,8,9)) return(3)
    if (v %in% c(11,12,13)) return(4)
    if (v %in% c(14,15,16)) return(5)
    if (v %in% c(3.1,3.2,3.3,3.4,4.1,4.2,4.3,4.4)) return(1)
    if (v %in% c(5.0,6.0,10.0)) return(2)
    if (v %in% c(7.1,7.2,7.3,7.4,8.1,8.2,9.1,9.2)) return(3)
    if (v %in% c(11.1,11.2,12.1,12.2,12.3,12.4,12.5,12.6,12.7,13.1,13.2,13.3,13.4,13.5)) return(4)
    if (v %in% c(14.1,14.2,14.3,15.0,16.0)) return(5)
    NA_real_
  })
}

# Function to read a file safely
read_wave <- function(path) {
  if (!file.exists(path)) return(NULL)
  df <- tryCatch(read_delim(path, delim = "\t", col_types = cols(), na = c("", "NA")), error = function(e) NULL)
  if (is.null(df) || nrow(df)==0) return(NULL)
  df
}

# Read waves with available files
wave4 <- read_wave("data/input/wave_four_lsype_young_person_2020.tab")
wave5 <- read_wave("data/input/wave_five_lsype_young_person_2020.tab")
wave6 <- read_wave("data/input/wave_six_lsype_young_person_2020.tab")
wave7 <- read_wave("data/input/wave_seven_lsype_young_person_2020.tab")
wave8 <- read_wave("data/input/ns8_2015_derived.tab")
wave9 <- read_wave("data/input/ns9_2022_main_interview.tab")

# Process each wave if present
if (!is.null(wave4)) {
  wave4 <- wave4 %>% mutate(nssec17_raw = recode_missing(W4nsseccatYP), nssec17 = map_major_nssec(nssec17_raw))
}
if (!is.null(wave5)) {
  wave5 <- wave5 %>% mutate(nssec18_raw = recode_missing(W5nsseccatYP), nssec18 = map_major_nssec(nssec18_raw))
}
if (!is.null(wave6)) {
  wave6 <- wave6 %>% mutate(nssec19_raw = recode_missing(w6nsseccatYP), nssec19 = map_major_nssec(nssec19_raw))
}
if (!is.null(wave7)) {
  wave7 <- wave7 %>% mutate(nssec20_raw = recode_missing(W7NSSECCat), nssec20 = map_major_nssec(nssec20_raw))
}
if (!is.null(wave8)) {
  wave8 <- wave8 %>% mutate(nssec25_raw = recode_missing(W8DNSSEC17), nssec25 = map_major_nssec(nssec25_raw))
}
if (!is.null(wave9)) {
  wave9 <- wave9 %>% mutate(nssec32_raw = recode_missing(W9NSSEC), nssec32 = map_major_nssec(nssec32_raw))
}

# Create minimal data frames with only ID and variable if wave missing
make_out <- function(df, var_name) {
  if (is.null(df)) return(data.frame(NSID = character(), !!sym(var_name) := numeric()))
  df %>% select(NSID, !!sym(var_name))
}

wave4_out <- make_out(wave4, "nssec17")
wave5_out <- make_out(wave5, "nssec18")
wave6_out <- make_out(wave6, "nssec19")
wave7_out <- make_out(wave7, "nssec20")
wave8_out <- make_out(wave8, "nssec25")
wave9_out <- make_out(wave9, "nssec32")

# Merge all waves
merged <- full_join(wave4_out, wave5_out, by = "NSID") %>%
  full_join(., wave6_out, by = "NSID") %>%
  full_join(., wave7_out, by = "NSID") %>%
  full_join(., wave8_out, by = "NSID") %>%
  full_join(., wave9_out, by = "NSID")

# Replace NAs with -3 (not asked)
merged[is.na(merged)] <- -3

# Write output
write_csv(merged, "data/output/cleaned_data.csv")

