library(readr)
library(dplyr)

recode_missing <- function(x) {
  x_num <- as.numeric(x)
  mapping <- list(
    `-999` = -2, `-998` = -2, `-997` = -2, `-995` = -2,
    `-1`   = -1, `-8`   = -8, `-92`  = -9, `-94` = -8,
    `-9`   = -9, `-99`  = -3, `-91`  = -1
  )
  res <- x_num
  for (i in seq_along(x_num)) {
    val <- x_num[i]
    if (!is.na(val) && val < 0) {
      key <- as.character(val)
      if (key %in% names(mapping)) {
        res[i] <- mapping[[key]]
      } else {
        res[i] <- -3
      }
    }
  }
  res
}

map_major_nssec <- function(vals) {
