# ------------------------------------------------------------------
# 1. Helper functions
# ------------------------------------------------------------------
# Convert negative missing codes to the standard sentinel values
recode_missing <- function(x) {
  x_num <- as.numeric(x)
  mapping <- list(
    `-999` = -2, `-998` = -2, `-997` = -2, `-995` = -2,
    `-1`   = -1, `-8`   = -8, `-92`  = -9, `-94` = -8,
    `-9`   = -9, `-99`  = -3, `-91`  = -1
  )
  res <- x_num
  for (i in seq_along(x_num)) {
    val <- x_num[i]
    if (!is.na(val) && val < 0) {
      key <- as.character(val)
      if (key %in% names(mapping)) {
        res[i] <- mapping[[key]]
      } else {
        res[i] <- -3      # default to “not asked”
      }
    }
  }
  res
}

# Map full NS‑SEC categories to the 5 major categories
map_major_nssec <- function(vals) {
  sapply(vals, function(v) {
    if (is.na(v)) return(NA_real_)
    # Major 1 – higher managerial & professional (codes 1‑6, 10)
    if (v %in% c(1,2,3,4,5,6,10)) return(1)
    # Major 2 – lower managerial & supervisory (codes 5,6,10)
    if (v %in% c(5,6,10)) return(2)
    # Major 3 – intermediate (codes 7‑9)
    if (v %in% c(7,8,9)) return(3)
    # Major 4 – routine & semi‑routine (codes 11‑13)
    if (v %in% c(11,12,13)) return(4)
    # Major 5 – non‑employed (codes 14‑16)
    if (v %in% c(14,15,16)) return(5)
    # Decimal codes for detailed categories
    if (v %in% c(3.1,3.2,3.3,3.4,4.1,4.2,4.3,4.4)) return(1)
    if (v %in% c(5.0,6.0,10.0)) return(2)
    if (v %in% c(7.1,7.2,7.3,7.4,8.1,8.2,9.1,9.2)) return(3)
    if (v %in% c(11.1,11.2,12.1,12.2,12.3,12.4,12.5,12.6,12.7,
                 13.1,13.2,13.3,13.4,13.5)) return(4)
    if (v %in% c(14.1,14.2,14.3,15.0,16.0)) return(5)
    NA_real_
  })
}

